WITH filtered_pages AS (SELECT cp.* FROM catalog_page cp WHERE cp.cp_start_date_sk >= 2450800 AND cp.cp_end_date_sk <= 2451200 AND cp.cp_catalog_page_number IN (1, 2, 3, 5, 6)), dept_reason_stats AS (SELECT cp.cp_department, r.r_reason_id, COUNT(*) AS page_count, AVG(cp.cp_catalog_page_number) AS avg_page_num, MIN(cp.cp_start_date_sk) AS min_start_date, MAX(cp.cp_end_date_sk) AS max_end_date FROM filtered_pages cp JOIN reason r ON cp.cp_type = r.r_reason_id GROUP BY cp.cp_department, r.r_reason_id), dept_totals AS (SELECT cp_department, SUM(page_count) AS total_pages FROM dept_reason_stats GROUP BY cp_department) SELECT drs.cp_department, r.r_reason_desc, drs.page_count, drs.avg_page_num, drs.min_start_date, drs.max_end_date, drs.page_count * 1.0 / dt.total_pages AS page_ratio, RANK() OVER (PARTITION BY drs.cp_department ORDER BY drs.page_count DESC) AS reason_rank_in_dept FROM dept_reason_stats drs JOIN dept_totals dt ON drs.cp_department = dt.cp_department JOIN reason r ON drs.r_reason_id = r.r_reason_id ORDER BY drs.cp_department, drs.page_count DESC
